import{_ as e,o as i,c as t,ag as o}from"./chunks/framework.CvgP6Fyv.js";const u=JSON.parse('{"title":"API For Docker","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),r={name:"README.md"};function l(s,a,n,h,d,c){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="api-for-docker" tabindex="-1">API For Docker <a class="header-anchor" href="#api-for-docker" aria-label="Permalink to &quot;API For Docker&quot;">​</a></h1><p>API For Docker 是一个基于多种编程语言的开放 API 平台，免费、不限调用，覆盖生活常用、出行服务、开发工具、金融服务、通讯服务和公益大数据等场景。 官网：<a href="https://api.isoyu.com/" target="_blank" rel="noreferrer">https://api.isoyu.com/</a></p><hr><h6 id="食-用方法-个人近十年整理维护的-api-大杂烩-按需增加功能。当前页面公开的接口约占全部接口的五分之一。" tabindex="-1">&quot;食&quot;用方法：个人近十年整理维护的 API 大杂烩，按需增加功能。当前页面公开的接口约占全部接口的五分之一。 <a class="header-anchor" href="#食-用方法-个人近十年整理维护的-api-大杂烩-按需增加功能。当前页面公开的接口约占全部接口的五分之一。" aria-label="Permalink to &quot;&quot;食&quot;用方法：个人近十年整理维护的 API 大杂烩，按需增加功能。当前页面公开的接口约占全部接口的五分之一。&quot;">​</a></h6><h6 id="服务长期运行在-linux-docker-容器中-数据存储以-oceanbase-为主。接口采用-rest-风格设计-请求地址可预期且面向资源-通过标准-http-状态码表达成功或失败-并使用-http-authentication-与标准请求方法提升易用性。所有-api-请求均返回规范友好的-json-含错误信息-。" tabindex="-1">服务长期运行在 Linux Docker 容器中，数据存储以 OceanBase 为主。接口采用 REST 风格设计，请求地址可预期且面向资源；通过标准 HTTP 状态码表达成功或失败；并使用 HTTP Authentication 与标准请求方法提升易用性。所有 API 请求均返回规范友好的 JSON（含错误信息）。 <a class="header-anchor" href="#服务长期运行在-linux-docker-容器中-数据存储以-oceanbase-为主。接口采用-rest-风格设计-请求地址可预期且面向资源-通过标准-http-状态码表达成功或失败-并使用-http-authentication-与标准请求方法提升易用性。所有-api-请求均返回规范友好的-json-含错误信息-。" aria-label="Permalink to &quot;服务长期运行在 Linux Docker 容器中，数据存储以 OceanBase 为主。接口采用 REST 风格设计，请求地址可预期且面向资源；通过标准 HTTP 状态码表达成功或失败；并使用 HTTP Authentication 与标准请求方法提升易用性。所有 API 请求均返回规范友好的 JSON（含错误信息）。&quot;">​</a></h6><hr><h6 id="须知-api-将记录你的域名、使用流量、调用次数等信息并存储六个月-如介意请勿使用。日单-ip-过千请申请加白。-统计信息-管理员邮箱-admin-isoyu-com" tabindex="-1">须知：API 将记录你的域名、使用流量、调用次数等信息并存储六个月，如介意请勿使用。日单 IP 过千请申请加白。 <a href="#">统计信息</a> 管理员邮箱：admin@isoyu.com <a class="header-anchor" href="#须知-api-将记录你的域名、使用流量、调用次数等信息并存储六个月-如介意请勿使用。日单-ip-过千请申请加白。-统计信息-管理员邮箱-admin-isoyu-com" aria-label="Permalink to &quot;须知：API 将记录你的域名、使用流量、调用次数等信息并存储六个月，如介意请勿使用。日单 IP 过千请申请加白。 [统计信息](#) 管理员邮箱：admin@isoyu.com&quot;">​</a></h6><hr><h6 id="条款-api-拥有所有运行权-在某些特定情况下-姬长信-api-有权禁止你的网站调用。" tabindex="-1">条款：API 拥有所有运行权，在某些特定情况下，姬长信 API 有权禁止你的网站调用。 <a class="header-anchor" href="#条款-api-拥有所有运行权-在某些特定情况下-姬长信-api-有权禁止你的网站调用。" aria-label="Permalink to &quot;条款：API 拥有所有运行权，在某些特定情况下，姬长信 API 有权禁止你的网站调用。&quot;">​</a></h6><hr><h6 id="警告-⚠️-禁止用于违法、商业用途。若发现有大批违禁滥用-会针对该功能加上授权码-仅供工信部备案、公安备案用户申请使用。" tabindex="-1">警告 ⚠️ 禁止用于违法、商业用途。若发现有大批违禁滥用，会针对该功能加上授权码，仅供工信部备案、公安备案用户申请使用。 <a class="header-anchor" href="#警告-⚠️-禁止用于违法、商业用途。若发现有大批违禁滥用-会针对该功能加上授权码-仅供工信部备案、公安备案用户申请使用。" aria-label="Permalink to &quot;警告 ⚠️ 禁止用于违法、商业用途。若发现有大批违禁滥用，会针对该功能加上授权码，仅供工信部备案、公安备案用户申请使用。&quot;">​</a></h6><hr><h6 id="不接受定制功能性捐助-who-has-donated-recently" tabindex="-1">不接受定制功能性捐助！<a href="https://github.com/insoxin/donate/blob/master/HISTORY.md" target="_blank" rel="noreferrer">Who has donated recently?</a> <a class="header-anchor" href="#不接受定制功能性捐助-who-has-donated-recently" aria-label="Permalink to &quot;不接受定制功能性捐助！[Who has donated recently?](https://github.com/insoxin/donate/blob/master/HISTORY.md)&quot;">​</a></h6><p>推荐 <a href="https://www.cloudflare.com/" target="_blank" rel="noreferrer">Cloudflare</a> 全球加速</p><h6 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to &quot;统计&quot;">​</a></h6><p>&lt;img src=&quot;<a href="https://api.isoyu.com/CloudflareTrafficCard/cf_svg.php?period=7d" target="_blank" rel="noreferrer">https://api.isoyu.com/CloudflareTrafficCard/cf_svg.php?period=7d</a>&quot; width=&quot;400&quot; height=&quot;40&quot; alt=&quot;svg&quot; /&gt;</p><p>&lt;img src=&quot;<a href="https://api.isoyu.com/CloudflareTrafficCard/cf_svg.php?period=30d" target="_blank" rel="noreferrer">https://api.isoyu.com/CloudflareTrafficCard/cf_svg.php?period=30d</a>&quot; width=&quot;400&quot; height=&quot;40&quot; alt=&quot;svg&quot; /&gt;</p><hr><h6 id="基于ta的作品" tabindex="-1"><a href="https://blog.isoyu.com/inso.html" target="_blank" rel="noreferrer">基于TA的作品</a> <a class="header-anchor" href="#基于ta的作品" aria-label="Permalink to &quot;[基于TA的作品](https://blog.isoyu.com/inso.html)&quot;">​</a></h6><hr><h6 id="api-接口列表" tabindex="-1">API 接口列表 <a class="header-anchor" href="#api-接口列表" aria-label="Permalink to &quot;API 接口列表&quot;">​</a></h6><ul><li>公益中国：宝贝回家核心数据 / 全国通缉令数据（SSL）/ AI 分析乳腺 X 线照片</li><li>新闻分类（头条/军事/娱乐/体育/科技/艺术/教育/要闻）数据接口</li><li>视频分类（精品视频/搞笑视频/美女视频/体育视频/新闻现场）接口</li><li>图片（cosplay）接口、花瓣相册接口</li><li>上海市政数据（数据由上海信息委提供）</li><li>段子笑话接口、天气预报接口</li><li>IT 资讯前端开发日报、知乎日报等</li><li>招聘信息</li><li>Bing 每日图片壁纸</li><li>二维码生成与解码（phpqrcode）</li><li>ARU（阿鲁）表情包 [作者授权]</li><li>图片反代（解决新浪图床反盗链）</li><li>内置动漫二次元美女图片壁纸：随机美女、宠物图片、随机动漫图片、随机抱枕图、卡通图片、二次元图片、IP 图片</li><li>开发杂类</li><li>QQ 昵称和头像接口</li><li>长网址缩短与还原</li><li>抖音去水印（作者 userId、抖音 id、昵称、头像、签名、视频资源 Id、视频信息、无水印视频等）</li><li>实时热搜（来源百度）</li><li>音频资源嗅探（p2p）</li><li>CSGO 账号信息查询</li><li>雅思成绩（以官网为准）</li><li>ISBN 查询</li><li>图片鉴黄</li><li>百度逆向 Link</li><li>待定...</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h2 id="docker" tabindex="-1">docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;docker&quot;">​</a></h2><ol><li>拉取镜像</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker pull insoxin/api:latest</span></span></code></pre></div><ol start="2"><li>运行容器</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker run -dit --name api -p 8080:80  --restart unless-stopped insoxin/api:latest</span></span></code></pre></div><p>访问 <code>IP:8080</code></p>',29)])])}const f=e(r,[["render",l]]);export{u as __pageData,f as default};
